We consider the following \textit{Linear Feasibility} (LF) problem:
\begin{align}
\label{eq:1}
Ax \leq b, \ \ b \in \R^m, \ A \in \R^{m\times n}.
\end{align}


\subsection{Notation}

We follow the standard linear algebra notation in this work. $\mathbb{R}^n$ denotes the $n$ dimensional real space, $\mathbb{R}^{m\times n}$ denotes the set of $m \times n$ real-valued matrices. For any matrix $A\in \mathbb{R}^{m\times n}$, $A^T$ denotes the transpose matrix $A$ and $a_i^T$ for $i = 1,2,..,m$ denotes the rows of matrix $A$. Furthermore, $P = \{x \in \R^n | \ Ax \leq b\}$ denotes the feasible region of the feasibility problem and $\mathcal{P}(x)$ denotes the projection of $x \in \R^n $ onto the feasible region $P$. The notation $d(x,P)$ denotes the distance between $x \in \R^n $ and the feasible region $P$, i.e., $d(x,P) \ = \ \inf_{z \in P} \|x-z\| \ = \ \|x-\mathcal{P}(x)\|$. For any matrix $A$, the spectral norm and Frobenius norm are denoted by $\|A\|$  and $\|A\|_F$, respectively. For any function $f:X\mapsto Y$, we use $\nabla f$ to represent the gradient of $f$. Finally, $\langle x,y\rangle = x^Ty$ denotes the standard inner product and $\|x\| = \sqrt{\langle x, x \rangle}$ as the euclidean ($L_2$) norm. The notation $x^+$ denotes the positive part of any real number (ie., $x^+ = \max \{x,0\}$). For any two arbitrary matrices $M,\ N$, the notation $M \succ N$ implies the positive definiteness of the matrix $M-N$. The notation $\E_\mathbb{S}[\cdot]$ is used to denote the expectation with respect to the sampling distribution $\mathbb{S}$. %Throughout the paper, we will frequently use the  tower property of expectation.


\subsection{Assumptions}
Throughout the paper, we assume that the system $Ax \leq b$ is consistent and the matrix $A$ has no zero rows. We also assumed that the rows of matrix $A$ are normalized (i.e., $\|a_i\|^2=1$ for all $i$). Note that, normalization simplifies the convergence analysis considerably. The normalization doesn't impact the computational time significantly (we could simply normalize each row for the first time it occurs during the computation). Moreover, normalization simplifies the convergence analysis considerably. In the description of algorithms, we do not enforce the assumption. Furthermore, it can be noted that the proposed algorithms generate the same iterates irrespective of normalization. 


\subsection{Expectation}
For the convergence analysis of Algorithm \ref{alg:skm} and its variations (any algorithm that uses that specific type of sampling distribution), we need to discuss a specific expectation calculation. First of all, let us sort the residual vector $(Ax-b)^+$ from smallest to largest for any iterate $x$ and denote $(Ax-b)^+_{\underline{\mathbf{i_j}}}$ as the $(\beta+j)^{th}$ entry on the sorted list \footnote{We use the notation $(Ax-b)^+_{\underline{\mathbf{i_j}}}$ throughout the paper to express the underlying expectation, where the indices $\underline{\mathbf{i_j}}$ represent the sampling process of \ref{eq:sampling}.}, i.e.,
\begin{align}
\label{eq:sampling}
  \underbrace{(Ax-b)^+_{\underline{\mathbf{i_0}}}}_{\beta^{th}} \ \leq ... \leq \ \underbrace{(Ax-b)^+_{\underline{\mathbf{i_j}}}}_{(\beta+j)^{th}} \ \leq ... \leq \ \underbrace{(Ax-b)^+_{\underline{\mathbf{i_{m-\beta}}}}}_{m^{th}}.
\end{align}
%Let's denote, the set $T(x)$\footnote{$|T(x)| = |T(x_k)| = m-\beta +1$. The notation $T(x_k)$ will be used to denote the corresponding set for any random iterate $x_k \in \R^n$.} as the collection of all indices from the list given in \eqref{eq:sampling}.
Now, consider the list with all of the entries of the residual vector $(Ax-b)^+$, then we need to calculate the probability that particular entry of the residual vector is selected at any given iteration. Note that, the probability that any sample is selected is $\frac{1}{\binom{m}{\beta}}$ and each sample has an equal probability of selection. Another intersecting fact can be noted that the size of the residual list controls the order and frequency that each entry of the residual vector will be expected to be selected. From now on, we will denote this specific choice of sampling distribution as $\mathbb{S}$ for any point $x \in \R^n$ \footnote{For ease of notation, throughout the paper, we will use $\mathbb{S}_k$ to denote the sampling distribution corresponding to any random iterate $x_k \in \R^n$ }. To calculate the resulting expectation with respect to the above-mentioned sampling distribution, let us first denote, $\tau \sim \mathbb{S}$ as the set of sampled $\beta$ constraints and $i^{*}$ as \footnote{ Similarly, we will use $\tau_k \sim \mathbb{S}_k$ to denote the sampled set and $i^* = \argmax_{i \in \tau_k \sim \mathbb{S}_k} \{a_i^Tx_k-b_i, 0\} \ = \ \argmax_{i \in \tau_k \sim \mathbb{S}_k} (A_{\tau_k}x_k-b_{\tau_k})^+_i$ for any iterate $x_k \in \R^n$.}
\begin{align}
\label{def:i1}
i^* = \argmax_{i \in \tau \sim \mathbb{S}} \{a_i^Tx-b_i, 0\} \ = \ \argmax_{i} (A_{\tau}x-b_{\tau})^+_i,
\end{align}
where, $A_{\tau}$ denotes the collection of rows of $A$ restricted to the index set $\tau$ and $(A_{\tau}x-b_{\tau})_i$ denotes the $i^{th}$ entry of $A_{\tau}x-b_{\tau}$. Using the above discussion with the list provided in equation \eqref{eq:sampling}, we have the following:
{\allowdisplaybreaks
\begin{align}
\label{def:exp}
\E_{\mathbb{S}} \left[\big |(a_{i^*}^Tx-b_{i^*})^{+}\big |^2\right] = \frac{1}{\binom{m}{\beta}} \sum\limits_{j = 0}^{m-\beta} \binom{\beta-1+j}{\beta-1} \big | (Ax-b)^{+}_{\underline{\mathbf{i_j}}} \big |^2, \end{align}}
where, $\E_{\mathbb{S}}$ denotes the required expectation corresponding to the sampling distribution $\mathbb{S}$. The above expectation calculation was first used by De Loera \textit{et.al} in their work \cite{haddock:2017} where they first introduced the SKM method.


\subsection{Function $f(x)$}
In this section, we formalize the definition of function $f:\R^n \rightarrow \R$. Throughout section \ref{sec:conv}, we will use the properties of function $f(x)$ \footnote{Similar type of functions with uniform sampling have been studied in \cite{needell:2016} \cite{razaviyayn:2019} in the context of stochastic gradient descent and alternating projection algorithms respectively.}. First, for any index $i$, let us define the following function
\begin{align}
\label{def:function_i}
    f_i(x) = \frac{1}{2} |(a_{i}^Tx-b_{i})^+|^2, \quad \nabla f_i(x) = (a_{i}^Tx-b_{i})^+ a_{i}.
\end{align}
Then to simplify the expectation expression of \eqref{def:exp} further, we define the function $f$ and the gradient of $f$ as follows:
\begin{align}
\label{def:function}
    f(x) =  \E_{\mathbb{S}}\left[f_{i^*}(x)\right], \quad \nabla f(x) = \E_{\mathbb{S}} \left[\nabla f_{i^*}(x)\right],
\end{align}
where, the index $i^*$ is selected by the rule provided in \eqref{def:i1}.


\begin{algorithm}
\caption{PASKM Algorithm: $x_{k+1} = \textbf{PASKM}(A,b,x_0,K, \delta, \beta)$}
\label{alg:paskm}
\begin{algorithmic}
\STATE{Initialize $v_0 \leftarrow x_0, \  k \leftarrow 0$;}
\WHILE{$k \leq K$}
\STATE{Choose $\gamma, \omega,  \alpha$ considering either \eqref{cond} or \eqref{eq:askm12} and update
\begin{align}
\label{eq:yk}
  y_k = \alpha v_k + (1-\alpha)x_k;
\end{align}}
\STATE{Choose a sample of $\beta$ constraints, $\tau_k$, uniformly at random from the rows of matrix $A$. From these $\beta$ constraints, choose $i^* = \argmax_{i \in \tau_k} \{a_i^Ty_k-b_i, 0\}$; \ Update 
\begin{align}
x_{k+1} & = y_k- \delta \frac{\left(a_{i^*}^Ty_k -b_{i^*}\right)^+}{\|a_{i^*}\|^2} a_{i^*}; \label{eq:askm1} \\
v_{k+1} & = \omega v_k+ (1-\omega)y_k-\gamma \frac{\left(a_{i^*}^Ty_k -b_{i^*}\right)^+}{\|a_{i^*}\|^2} a_{i^*}; \label{eq:askm2}
\end{align}
}
\STATE{$k \leftarrow k+1$;}
\ENDWHILE
\RETURN $x$
\end{algorithmic}
\end{algorithm}


\begin{mdframed}[backgroundcolor=gray!15,   topline=false,   bottomline =false,   rightline=false,   leftline=false] \begin{lemma}
\label{lem0}
(Hoffman \cite{hoffman}, Theorem 4.4 in \cite{lewis:2010}) Let $x \in \R^n$ and $P$ be the feasible region, then there exists a constant $L > 0$ such that the following identity holds:
\begin{align*}
  d(x,P)^2 \leq L^2 \ \|(Ax-b)^+\|^2.
\end{align*}
\end{lemma} \end{mdframed}


\begin{mdframed}[backgroundcolor=gray!15,   topline=false,   bottomline =false,   rightline=false,   leftline=false] \begin{lemma}
\label{lem:skmseq}
(Lemma 2.1 in \cite{haddock:2017})  Let $\{x_k\},\ \{y_k\}$ be real non-negative sequences such that $x_{k+1} > x_k > 0$ and $y_{k+1} \geq y_k \geq 0$, then
\begin{align*}
  \sum\limits_{k=1}^{n} x_k y_k \ \geq \   \sum\limits_{k=1}^{n} \overline{x} y_k, \quad \text{where} \ \ \overline{x} = \frac{1}{n}\sum\limits_{k=1}^{n} x_k.
\end{align*}
\end{lemma} \end{mdframed}


\begin{mdframed}[backgroundcolor=gray!15,   topline=false,   bottomline =false,   rightline=false,   leftline=false] \begin{lemma}
\label{lem:distance}
For any $x \in \R^n$ and $\bar{x} \in P$, the following identity holds,
\begin{align*}
    d(x,P)^2 \ = \ \|x-\mathcal{P}(x) \|^2 \ \leq \ \|x-\bar{x} \|^2.
\end{align*}
\end{lemma} \end{mdframed}


\begin{align}
\label{eq:askm12}
\zeta =\frac{3.99\eta \mu_1}{(1-\mu_1)^2} , \ \omega = 1-\frac{\zeta \mu_1^2+2\gamma \mu_1-\zeta \mu_1}{1+\zeta \mu_1^2} , \ \ \gamma = \sqrt{ \zeta \eta \mu_1}, \ \ \alpha = \frac{ \eta}{ \eta + \gamma },
\end{align}

