\begin{lemma}
\label{lem1}
Let $\lambda_j$ be the $j^{th}$ eigenvalue of the matrix $W = \E_{\mathbb{S}}\left[a_{i^*}a_{i^*}^T\right]$, then for all $j$, the bound $0 \leq \lambda_j \leq 1$ holds.
\end{lemma}

\begin{proof}
Since $W$ is positive semi-definite, we can write $\lambda_j \geq 0$ for all $j$. Also as the mapping $\lambda_{\max}(X)$ is convex, using Jensen's inequality we have,
\begin{align*}
    \lambda_{\max} (W) = \lambda_{\max} \left[ \E_{\mathbb{S}} \left[a_{i^*}a_{i^*}^T\right] \right] \leq \E_{\mathbb{S}} \left[\lambda_{\max}\left(a_{i^*}a_{i^*}^T\right)\right] \leq 1.
\end{align*}
\end{proof}

\begin{lemma}
\label{lem2}
For any $1 \leq \beta \leq m$, we have the following:
\begin{align*}
 \E_{\mathbb{S}} \left[a_{i^*}a_{i^*}^T\right] \preceq \frac{\beta}{m} A^TA.
\end{align*}
\end{lemma}

\begin{proof}
See Appendix 1.
\end{proof}

\begin{lemma}
\label{lem3}
For any $x \in \R^n$ with $\lambda_{\max} = \lambda_{\max}(A^TA)$, we have the following:
\begin{align*}
    \frac{\mu_1}{ 2} \ d(x,P)^2 \ \leq \ f(x) \ \leq \  \frac{\mu_2}{2}\ d(x,P)^2,
\end{align*}
with $ 0 < \mu_1 = \frac{1}{m L^2} \leq \ \mu_2 = \min \left\{1, \frac{\beta}{m} \lambda_{\max}\right\} \leq 1$. 
\end{lemma}

\begin{proof}
See Appendix 1.
\end{proof}

\begin{lemma}
\label{lem:grad}
For any $x, y \in \R^n$, we have the following:
\begin{align*}
 \langle  x-y, \E_{\mathbb{S}}  \left[(a_{i^*}^Ty-b_{i^*})^{+} a_{i^*}\right]  \rangle  & =  \langle  x-y, \nabla f(y)   \rangle   \\
 & \leq    f(x) - f(y) \leq     \frac{\mu_2}{2} \ d(x,P)^2 -  \frac{\mu_1}{2} \ d(y,P)^2.
\end{align*}
\end{lemma}

\begin{proof}
See Appendix 1.
\end{proof}

\begin{lemma}
\label{lem:grad1}
For any $y \in \R^n$ and $\bar{y}$ such that $A \bar{y} \leq b$, we have the following:
\begin{align*}
\langle  \bar{y}-y, \E_{\mathbb{S}} \left[a_{i^*}(a_{i^*}^Ty-b_{i^*})^{+}\right]  \rangle = \ \langle  \bar{y}-y, \nabla f(y)  \rangle    \leq  -2f(y)  \leq \ - \mu_1  d(y,P)^2.
\end{align*}
\end{lemma}

\begin{proof}
See Appendix 1.
\end{proof}

\begin{lemma}
\label{lem4}
For any $x \in \R^n$ and $0 < \delta < 2$, we have the following:
\begin{align*}
  \E_{\mathbb{S}} \left[ d(z,P)^2\right] = \E_{\mathbb{S}} \left[ \Big \| x- \mathcal{P} (x) - \delta \left(a_{i^*}^Tx-b_{i^*}\right)^+ a_{i^*}\Big \|^2 \right]  \leq   h(\delta) \ d(x,P)^2,
\end{align*}
where, $z = x - \delta \left(a_{i^*}^Tx-b_{i^*}\right)^+ a_{i^*}$, $ \eta = 2 \delta -\delta^2$ and $h(\delta) = 1- \eta \mu_1 < 1$.
\end{lemma}

\begin{proof}
See Appendix 1.
\end{proof}

