    & =  \frac{1}{\binom{m}{\beta}} (x-\mathcal{P} (x))^T\sum\limits_{j = 0}^{m-\beta} \binom{\beta-1+j}{\beta-1} \ (A^TA)_{\underline{\mathbf{i_j}}} (x-\mathcal{P} (x) ) \\
    & =  (x-\mathcal{P} (x) )^T \E_{\mathbb{S}} \left[a_{i^*}a_{i^*}^T\right] (x-\mathcal{P} (x) ) \\
    & \overset{\text{Lemma} \ \ref{lem1} \ \& \ \ref{lem2} }{\leq} \  \min \left\{1, \frac{\beta}{m} \lambda_{\max}\right\} \big \| x- \mathcal{P} (x) \big \|^2 \\
    & = \  \min \left\{1, \frac{\beta}{m} \lambda_{\max}\right\} d(x,P)^2.
\end{align*}
Combining the above identities and using the expression for $f(x)$ from \eqref{def:function} we get,
\begin{align*}
    \frac{\mu_1}{ 2} \ d(x,P)^2 \ \leq \ f(x) \ \leq \  \frac{\mu_2}{2} \ d(x,P)^2,
\end{align*}
which proves the Lemma. 

\paragraph{Proof of Lemma \ref{lem:grad}}

From the definition of $f(x)$, it can be easily checked that $f(x)$ is a convex function. Now, by the convexity property of $f(x)$, for any $x, y \in \R^n$, we have the following:
\begin{align}
\label{eq:grad}
    \langle x-y, \nabla f(y) \rangle \leq f(x) - f(y).
\end{align}
Therefore, we have
\begin{align*}
\big \langle  x-y, \E_{\mathbb{S}}  \left[(a_{i^*}^Ty-b_{i^*})^{+} a_{i^*}\right] \big \rangle & =  \langle x-y, \nabla f(y) \rangle  \leq  \ f(x) - f(y) \\
&  \overset{\text{Lemma} \  \ref{lem3} }{\leq}  \    \frac{\mu_2}{2} \ d(x,P)^2 -  \frac{\mu_1}{2} \ d(y,P)^2.
\end{align*}
This completes the proof.


\paragraph{Proof of Lemma \ref{lem:grad1}}

\iffalse

Let's denote, $ \mathcal{J} = \{i_j \ | \ c_{i_j}^Ty-d_{i_j} \geq 0, \ i_j \in T(y)\}$. Then following the construction of \eqref{eq:f}, the function $f(y)$ can be expressed as $f(y) = \|C_{\mathcal{J}} y-d_{\mathcal{J}} \|^2$.
Since, $C_{\mathcal{J}} y-d_{\mathcal{J}} \geq 0$ and $C_{\mathcal{J}}\bar{y}-d_{\mathcal{J}} \leq 0$, we have,
\begin{align*}
    \big \langle C_{\mathcal{J}}y-d_{\mathcal{J}} , C_{\mathcal{J}}\bar{y}-d_{\mathcal{J}} \big \rangle \ \leq \ 0.
\end{align*}
Adding $\|C_{\mathcal{J}}y-d_{\mathcal{J}}\|^2$ to both sides and rearranging terms we get,
\begin{align}
\label{eq:grad1}
 \|C_{\mathcal{J}}y-d_{\mathcal{J}} \|^2 \ \leq \  \big \langle C_{\mathcal{J}}^T \left( C_{\mathcal{J}}y-d_{\mathcal{J}} \right), y - \bar{y} \big \rangle.
\end{align}

\fi

Since, $\bar{y} \in P$, from the definition we have,
\begin{align*}
   \langle  \bar{y}-y, \E_{\mathbb{S}}  \left[a_{i^*}(a_{i^*}^Ty-b_{i^*})^{+}\right]  \rangle \ & = \E_{\mathbb{S}} \left[(a_{i^*}^Ty-b_{i^*})^{+} \left(a_{i^*}^T\bar{y}- a_{i^*}^T y\right)\right] \\
   & \leq \E_{\mathbb{S}} \left[(a_{i^*}^Ty-b_{i^*})^{+} \left(b_{i^*}- a_{i^*}^T y\right)\right] \\
   & = - \E_{\mathbb{S}} \left[\big | (a_{i^*}^Ty-b_{i^*})^{+} \big |^2\right] \\
   &= - 2f(y) \overset{\text{Lemma} \ \ref{lem3} }{\leq} \ \ -\mu_1 \ d(y,P)^2.
\end{align*}
Here, we used the identity $xx^+ = |x^+|^2$. This proves the Lemma.

\paragraph{Proof of Lemma \ref{lem4}}

Since, $\mathcal{P}(x) \in P$, we have
{\allowdisplaybreaks
\begin{align*}
    \E_{\mathbb{S}}  \left[ d(z,P)^2\right] &  \overset{\text{Lemma} \ \ref{lem:distance}}{\leq} \  \E_{\mathbb{S}}  \left[ \|z- \mathcal{P}(x)\|^2\right] = \E_{\mathbb{S}} \left[ \big \| x- \mathcal{P} (x) - \delta \left(a_{i^*}^Tx-b_{i^*}\right)^+ a_{i^*} \big \|^2 \right] \\
    & \overset{\eqref{def:function}}{=} \ \|x - \mathcal{P} (x) \|^2 + 2\delta^2 f(x)  + 2 \delta \ \big  \langle  \mathcal{P}(x)-x, \nabla f(x) \big \rangle \\
    & \overset{\text{Lemma} \ \ref{lem3} }{\leq} \ \|x - \mathcal{P} (x) \|^2 -2(2\delta-\delta^2) f(x) \\
    & \leq \ \|x-  \mathcal{P} (x) \|^2 - (2\delta-\delta^2) \ \mu_1  \|x-  \mathcal{P} (x) \|^2 = h(\delta) \ d(x,P)^2.
\end{align*}}
Here, we used the lower bound of the expected value from Lemma \ref{lem3}.

\paragraph{Proof of Theorem \ref{th:10}}

Let us define, $\mathcal{V} = \omega \mathcal{P}(v_{k}) +(1-\omega) \mathcal{P}(y_{k}) $. Since $\mathcal{V} \in P$, using the update formula of $v_{k+1}$ from equation \eqref{eq:askm2}, we have,
\allowdisplaybreaks{
\begin{align}
\label{eq:askm4}
    d(v_{k+1},P)^2 & = \|v_{k+1} - \mathcal{P}(v_{k+1})\|^2 \overset{\text{Lemma} \ \ref{lem:distance}}{\leq}  \|v_{k+1} - \mathcal{V}\|^2  \nonumber \\
    & \overset{\eqref{eq:askm2}}{=}  \big \|\omega v_k + (1-\omega) y_k- \mathcal{V} -\gamma (a_{i^*}^Ty_k- b_{i^*})^+ a_{i^*} \big \|^2 \nonumber \\
    & =   \underbrace{ \|\omega v_k + (1-\omega) y_k- \mathcal{V} \|^2}_{I_1} + \gamma^2 \underbrace{\|(a_{i^*}^Ty_k- b_{i^*})^+a_{i^*}\|^2}_{I_2} \nonumber \\
    & - 2 \gamma  \underbrace{\big \langle \omega v_k + (1-\omega) y_k- \mathcal{V} \ ,\  a_{i^*} (a_{i^*}^Ty_k-b_{i^{*}})^{+} \big \rangle }_{I_3} \nonumber \\
    & = I_1 + \gamma^2 I_2 -2 \gamma I_3.
\end{align}}
Since $\|\cdot\|^{2}$ is a convex function and $0 < \omega < 1$, we can bound the expected first term as follows,
\begin{align}
\label{eq:askm5}
    \E_{\mathbb{S}_k} [I_1]  &= \E_{\mathbb{S}_k} \left[\|\omega v_k + (1-\omega) y_k-\mathcal{V}\|^2\right] \nonumber \\
    & = \E_{\mathbb{S}_k} \left[\|\omega v_k + (1-\omega) y_k- \omega \mathcal{P}(v_{k}) - (1-\omega) \mathcal{P}(y_{k})\|^2\right] \nonumber \\
    & \leq \omega \| v_k-\mathcal{P}(v_{k})\|^2 + (1-\omega) \|y_k-\mathcal{P}(y_{k})\|^2\nonumber \\
    & =  \omega \ d(v_k,P)^2 + (1-\omega) \ d(y_k,P)^2.
\end{align}
Taking expectation with respect to the sampling distribution in the second term of equation \eqref{eq:askm4} and using Lemma \ref{lem4} with the choice $z = x_{k+1}, \ x = y_k$ and $\eta = 2\delta-\delta^2$, we get,
\begin{align}
\label{eq:askm6}
   \gamma^2 \E_{\mathbb{S}_k} \left[\|(a_{i^*}^Ty_k- b_{i^*})^+ a_{i^*}\|^2\right] & \ = \  \gamma^2 \E_{\mathbb{S}_k} \left[|(a_{i^*}^Ty_k- b_{i^*})^+ |^2\right] \nonumber \\
    \overset{\text{Lemma} \ \ref{lem4}}{\leq} & \ \frac{\gamma^2 }{\eta} \left[d(y_k,P)^2 - \E \left[ d(x_{k+1},P)^2 \right]\right].
\end{align}

Now, taking expectation in the third term of \eqref{eq:askm4} we get,
\begin{align}
\label{eq:askm9}
    - 2  \gamma  \E_{\mathbb{S}_k} & [I_3 ]  = - 2 \gamma \big \langle \omega v_k + (1-\omega) y_k-\mathcal{V}, \E_{\mathbb{S}_k} \left[ a_{i^*} (a_{i^*}^Ty_k-b_{i^*})^{+}\right]  \big \rangle \nonumber \\
    & \overset{\eqref{eq:yk} \ \& \ \eqref{def:function} }{=} - 2 \gamma \big \langle \frac{\omega}{\alpha} \left[y_k - (1-\alpha) x_k\right] + (1-\omega) y_k-\mathcal{V},  \nabla f(y_k)  \big \rangle \nonumber \\
    & = - 2 \gamma \big \langle \frac{\omega(1-\alpha)}{\alpha}(y_k-x_k)+ y_k-\mathcal{V}, \nabla f(y_k)  \big \rangle.
\end{align}
Using Lemma \ref{lem:grad} and Lemma \ref{lem:grad1} we can simplify equation \eqref{eq:askm9} as follows,
\begin{align}
\label{eq:askm10}
  & \ -  2 \gamma  \E_{\mathbb{S}_k}  [I_3 ]  =   - 2 \gamma \big \langle \frac{\omega(1-\alpha)}{\alpha}(y_k-x_k)+ y_k-\mathcal{V}, \nabla f(y_k)  \big \rangle \nonumber \\
    & \quad =    2 \gamma \frac{\omega(1-\alpha)}{\alpha} \big \langle x_k-y_k, \nabla f(y_k)  \big \rangle + 2 \gamma \big \langle \mathcal{V}-y_k, \nabla f(y_k)  \big \rangle \nonumber \\
  & \overset{\text{Lemma} \ \ref{lem:grad} \ \& \ \ref{lem:grad1}}{\leq} \frac{\gamma \omega (1-\alpha)}{\alpha} \  d(x_k,P)^2 - \frac{ \mu_1 \gamma  \omega (1-\alpha)}{\alpha} \ d(y_k,P)^2 - 2 \mu_1 \gamma \ d(y_k,P)^2.
\end{align}
Now, substituting the values of equation \eqref{eq:askm5}, \eqref{eq:askm6} \& \eqref{eq:askm10} in equation \eqref{eq:askm4} we get the following:
\allowdisplaybreaks{
\begin{align*}
 \E [ & d(v_{k+1} ,P)^2  ]  =  I_1 + \gamma^2 \E_{\mathbb{S}_k}[I_2 ]- 2 \gamma \E_{\mathbb{S}_k}[I_3] \nonumber \\
 & = \omega \ d(v_{k},P)^2 + (1-\omega) \ d(y_k,P)^2 + \frac{\gamma^2 }{\eta} \left\{d(y_k,P)^2 - \E \left[ d(x_{k+1},P)^2 \right]\right\} \nonumber \\
 & \quad + \frac{\gamma \omega (1-\alpha)}{\alpha}  d(x_k,P)^2 - \gamma \mu_1 \left(2+\frac{ \omega (1-\alpha)}{\alpha}\right)  d(y_k,P)^2.
\end{align*}}
With further simplification, the above identity can be written as follows:
\allowdisplaybreaks{
\begin{align}
\label{eq:askm11}
 & \E \left[ d(v_{k+1},P)^2 + \frac{\gamma^2}{\eta} d(x_{k+1},P)^2 \right]  = \omega \ \left[d(v_{k},P)^2 + \frac{\gamma (1-\alpha)}{\alpha} d(x_{k},P)^2 \right] \nonumber \\
 & \quad \quad \quad \quad \quad \quad \quad + d(y_k,P)^2 \ \left\{1-\omega+ \frac{\gamma^2 }{\eta}  - 2\gamma \mu_1 - \frac{\gamma \omega \mu_1 (1-\alpha)}{\alpha}  \right\}.
\end{align}}
Now, let's choose the parameters as in equation \eqref{eq:askm12} along with $0 < \zeta  < \frac{4\eta \mu_1}{(1-\mu_1)^2} $. We can easily see that $\frac{\gamma^2 }{\eta} = \frac{ \gamma(1-\alpha)}{\alpha}$ and $ \alpha \in (0,1)$. Also note that,
\allowdisplaybreaks{\begin{align}
 2 \mu_1 \gamma \ = \ 2 \mu_1 \sqrt{\eta \zeta \mu_1} \ > \ 2 \mu_1 \sqrt{\frac{\zeta (1-\mu_1)^2 \zeta}{4}} = \mu_1 \zeta(1-\mu_1),
\end{align}}
which implies $\omega < 1$. Similarly, whenever $\mu_1 < 1$ we have
\begin{align}
    2\gamma - \zeta - \frac{1}{\mu_1} < 2\sqrt{\eta \mu_1 \zeta} - \zeta - 1 \leq  2 \sqrt{\zeta} - \zeta - 1  = -(\sqrt{\zeta}-1)^2 \leq 0,
\end{align}
which implies $\omega > 0$. Also, using the parameter choice of \eqref{eq:askm12}, we have, 
\begin{align}
\label{eq:askm13}
  1-\omega+ \frac{\gamma^2 }{\eta}  - 2\gamma \mu_1 - & \frac{\gamma \omega \mu_1 (1-\alpha)}{\alpha}   = 1-\omega + \zeta \mu_1 - 2\gamma \mu_1 - \omega \zeta \mu_1^2 \nonumber \\
  & = 1- 2\gamma \mu_1 + \zeta \mu_1 - \omega (1+\zeta \mu_1^2) = 0.
\end{align}
Now, using all of the above relations (equation \eqref{eq:askm12}, \eqref{eq:askm13}) in equation \eqref{eq:askm11}, we get the following:
\begin{align}
\label{eq:askm14}
  \E \left[ d(v_{k+1},P)^2 + \frac{\gamma^2}{\eta} d(x_{k+1},P)^2 \right] &  \ \leq \ \omega \Big[d(v_{k},P)^2 + \underbrace{\frac{\gamma (1-\alpha)}{\alpha}}_{= \frac{\gamma^2 }{\eta}} \ d(x_{k},P)^2 \Big] \nonumber \\
  + & \Big [\underbrace{1-\omega+ \frac{\gamma^2 }{\eta}  - 2\gamma \mu_1 - \frac{\gamma \omega \mu_1 (1-\alpha)}{\alpha} }_{= \ 0} \Big ] \ d(y_k,P)^2 \nonumber \\
   = \ & \omega \ \left[ d(v_{k},P)^2+ \frac{\gamma^2}{\eta} d(x_{k},P)^2 \right].
\end{align}
Finally, taking expectation again with tower rule and substituting $\frac{\gamma^2 }{\eta}= \zeta \mu_1 $ we have,
\begin{align*}
\E \left[ d(v_{k+1},P)^2 + \zeta \mu_1 \  d(x_{k+1},P)^2 \right] \ & \leq \ \omega^{k+1} \ \E \left[ d(v_{0},P)^2+ \zeta \mu_1 \  d(x_{0},P)^2 \right] \\
& = (1+\zeta \mu_1) \ \omega^{k+1} \ d(x_{0},P)^2.
\end{align*}
This proves the Theorem. Furthermore, for faster convergence, we need to choose parameters such that, $\omega$ becomes as small as possible. In the proof, we assumed $\mu_1 <1$ holds which is the most probable scenario. Whenever $\mu_1 = 1$, we must have $\mu_1 = \mu_2 =1$ and Lemma 6 holds with both equality, i.e., $f(x) = d(x,P)^2$. Therefore if we choose $\alpha, \gamma, \omega$ as $\alpha = \frac{\eta}{\eta+ \gamma}, \ \gamma = \sqrt{\zeta \eta}, \ \omega = 1- \frac{2\gamma}{1+\zeta}$, we can check that condition (89) holds and $0 < \omega < 1$ holds for any $\zeta > 0$.

